// === Tab: mySketch ===
let layers = 6;
let leaf = 2;

function setup() {
  createCanvas(500, 500);
  strokeWeight(1.3);
  colorMode(HSB, 40);
  background(0);
}

let bghue = 0

// Easing function: easeOutElastic
function easeOutElastic(t) {
  let c4 = (2 * PI) / 9;

  if (t === 0) return 0;
  if (t === 1) return 1;

  return pow(4, -80 * t) * sin((t * 90 - 0.5) * c4) + 1;
}

function draw() {
  let bounce = sqrt(easeOutElastic(millis()%90/10.0));

  background(0, 100, 00, 1);
  for (let i = 0; i < layers; i++) {
    let timer = millis() / ((millis()%6000/1000)*100+6000)*.1;
    let rotation = (PI / leaf) * timer * i * 6;

    // size
    let size_ = min(width / 9, height / 9);
    let perlin = pow(noise(millis() / 200.0 + i * 0.5), 2.4);
    let radius = size_ * (1-(i / layers));
    radius *= 1.5;

    // color
    let epylepsy = noise(millis() / 50.0) * 10;
    let perlin2 = noise(millis() / 888.0 + i * 0.1 + 10000) * epylepsy % 10;
    stroke(
      perlin2 / 5 + 20,
      randomGaussian(6000, 7) + noise(millis()/1000.0)*800,
      randomGaussian(100, 1),
      20
      )
    fill(
      perlin2,
      100+randomGaussian(90, 3) + noise(millis()/1000.0)*90,
      -100-randomGaussian(800, 1),
      20
    );

    for (let i = 0; i < leaf; i++) {
      let c = cos(TAU * i / leaf + rotation) * bounce;
      let d = sin(TAU * i / leaf + rotation) * bounce;

      rectMode(CENTER)
      rect(width / 2 + (c * radius), 
              height / 2 + (d * radius),
              radius * perlin, 
              radius * perlin,           
             )
      // ellipse();
    }
  }
}

